class Point:
    def __init__(self, x, y, label="origin"):
        self.x = x
        self.y = y
        self.label = label

    def __eq__(self, other):
        return (
            isinstance(other, Point)
            and self.x == other.x
            and self.y == other.y
            and self.label == other.label
        )

    def __repr__(self):
        return f"Point(x={self.x}, y={self.y}, label={self.label!r})"

