from point import Point


def test_fields_and_default():
    p = Point(1, 2)
    assert (p.x, p.y, p.label) == (1, 2, "origin")


def test_equality_uses_all_fields():
    assert Point(1, 2, "a") == Point(1, 2, "a")
    assert Point(1, 2, "a") != Point(1, 2, "b")
    assert Point(1, 2) != Point(1, 3)


def test_repr_format():
    assert repr(Point(1, 2, "x")) == "Point(x=1, y=2, label='x')"

